/**
 * Everything the owner's resume pipeline produces from a fixed palette, through
 * the module APIs that existed before per-user scoping, called the way they
 * were called then (no scope argument, so the owner's).
 *
 * owner.json was generated by running this against the code BEFORE per-user
 * blocks landed (`node --import ./worker/tests/register.mjs
 * worker/tests/golden/write-owner-golden.ts`). owner-golden.test.ts runs it
 * against the current code and requires the same bytes: the owner's KV keys,
 * assembled resumes, every LLM prompt, every cache key and every response.
 */
import { getAllBlocks } from '../../src/blocks.js'
import { upsertBlock, reorderBlocks, deleteBlock, exportBlocks } from '../../src/builder.js'
import { assembleResume, filterCanonical } from '../../src/skeleton.js'
import { getResumeContent, getFullSystemPrompt } from '../../src/resume.js'
import { generateTailoredResume } from '../../src/tailored-resume.js'
import { generateCoverLetter } from '../../src/cover-letter.js'
import { generateApplicationExtras } from '../../src/application-extras.js'
import { generateFormAnswers } from '../../src/form-answers.js'
import { getVariant, listVariants, mintVariant, renderVariant } from '../../src/variants.js'
import { CONTACT_KEY } from '../../src/contact.js'
import { MemoryKV } from '../helpers/kv.js'
import { fakeLLM } from '../helpers/llm.js'
import { OWNER_BLOCKS } from '../fixtures/owner-blocks.js'

const JOB = {
  job_title: 'Senior Platform Engineer',
  company: 'Initech',
  description: '<p>Build the search platform. Go, Kubernetes, ranking.</p>'
}

const CONTACT = {
  name: 'Jordan Example',
  email: 'jordan@example.com',
  phone: '+1 555 0100',
  linkedin: 'linkedin.com/in/jordan-example',
  github: 'github.com/example',
  location: 'Springfield',
  work_auth: 'Authorized to work in the US',
  relocation: 'Remote preferred',
  salary_line: 'Targeting 150k base'
}

/** created_at is wall-clock; everything else is deterministic. */
function stable(value: unknown): unknown {
  return JSON.parse(JSON.stringify(value), (k, v: unknown) => (k === 'created_at' ? '<time>' : v))
}

function snapshot(kv: MemoryKV): Record<string, string> {
  const out: Record<string, string> = {}
  for (const k of kv.keys()) {
    const raw = kv.store.get(k) as string
    let value: string
    try {
      value = JSON.stringify(stable(JSON.parse(raw)))
    } catch {
      value = raw
    }
    out[k] = value
  }
  return out
}

export async function computeOwnerGolden(): Promise<Record<string, unknown>> {
  const kv = new MemoryKV()
  const KV = kv.asKV()
  const golden: Record<string, unknown> = {}

  for (const block of OWNER_BLOCKS) await upsertBlock(KV, block)
  golden.keysAfterUpsert = kv.keys()
  golden.index = await kv.get('resume:blocks:index')

  const blocks = await getAllBlocks(KV)
  golden.assembledAll = assembleResume(blocks)
  golden.assembledCanonical = assembleResume(filterCanonical(blocks))
  golden.resumeContent = await getResumeContent({ CONTENT_KV: KV })
  await kv.put('resume:prompt', 'You are a resume assistant.')
  golden.systemPrompt = await getFullSystemPrompt({ CONTENT_KV: KV }, 'Jordan Example')

  // Tailoring: the selector picks a few ids including both summaries and every
  // Contoso detail, so variant dedup, the project floor and the page-1 budget
  // all run.
  const tailorLLM = fakeLLM({
    select: () => [
      'summary-ml',
      'summary-platform',
      'exp-contoso-search',
      'exp-contoso-infra',
      'proj-game',
      'not-a-block'
    ]
  })
  const tailored = await generateTailoredResume(tailorLLM.chain, KV, JOB)
  golden.tailored = tailored
  golden.tailoredPrompts = tailorLLM.prompts
  golden.tailoredCached = await generateTailoredResume(tailorLLM.chain, KV, JOB)
  golden.keysAfterTailor = kv.keys()

  const letterLLM = fakeLLM()
  golden.coverLetter = await generateCoverLetter(
    letterLLM.chain,
    KV,
    golden.resumeContent as string,
    JOB
  )
  golden.coverLetterPrompts = letterLLM.prompts
  golden.keysAfterLetter = kv.keys()

  await kv.put(CONTACT_KEY, JSON.stringify(CONTACT))
  const extrasLLM = fakeLLM()
  golden.extras = await generateApplicationExtras(extrasLLM.chain, KV, {
    ...JOB,
    resume_markdown: tailored.resume_markdown,
    job_location: 'Remote',
    workplace_type: 'remote'
  })
  golden.formAnswers = await generateFormAnswers(extrasLLM.chain, KV, {
    ...JOB,
    resume_markdown: tailored.resume_markdown,
    contact: CONTACT,
    questions: ['Why Initech?']
  })
  golden.extrasPrompts = extrasLLM.prompts
  golden.keysAfterExtras = kv.keys()

  // Variants: one per content path the owner uses.
  const mintLLM = fakeLLM()
  const byMarkdown = await mintVariant(mintLLM.chain, KV, {
    label: 'Initech packet',
    slug: 'owner-md',
    markdown: '# Jordan Example\n\n# Projects\n\nA rewritten anchor.\n\n### AI & Agents\n\nx',
    cover_letter_markdown: 'Dear Initech',
    company: 'Initech',
    job_title: 'Senior Platform Engineer',
    ttl_days: 30
  })
  const byBlocks = await mintVariant(mintLLM.chain, KV, {
    label: 'Blocks only',
    slug: 'owner-blocks',
    block_ids: ['header', 'summary-ml', 'education']
  })
  const byTailoring = await mintVariant(mintLLM.chain, KV, {
    label: 'Tailored at mint',
    slug: 'owner-tailored',
    ...JOB,
    profile_type: 'platform'
  })
  golden.variants = stable([byMarkdown, byBlocks, byTailoring])
  golden.mintPrompts = mintLLM.prompts
  // Sorted by slug: three mints can share a millisecond, and listVariants
  // orders by created_at.
  golden.variantList = (stable(await listVariants(KV)) as { slug: string }[]).sort((a, b) =>
    a.slug.localeCompare(b.slug)
  )
  const fetched = await getVariant(KV, 'owner-md')
  golden.renderedMarkdownVariant = fetched ? await renderVariant(KV, fetched) : null
  const fetchedBlocks = await getVariant(KV, 'owner-blocks')
  golden.renderedBlocksVariant = fetchedBlocks ? await renderVariant(KV, fetchedBlocks) : null
  golden.ttls = Object.fromEntries([...kv.ttls.entries()].sort(([a], [b]) => a.localeCompare(b)))

  // Builder writes bust the derived caches and keep the index in order.
  await reorderBlocks(KV, [...(JSON.parse(golden.index as string) as string[])].reverse())
  await deleteBlock(KV, 'proj-odd')
  golden.exported = await exportBlocks(KV)
  golden.finalStore = snapshot(kv)

  return golden
}
